('00000000-0000-0000-0022-000000000001', '00000000-0000-0000-0015-000000000043', '00000000-0000-0000-0002-000000000001', '00000000-0000-0000-0003-000000000001',
 5, 'Wanchai was punctual and professional. Guests loved him. Highly recommend.', '2026-04-03 12:00:00'),
('00000000-0000-0000-0022-000000000002', '00000000-0000-0000-0015-000000000044', '00000000-0000-0000-0002-000000000003', '00000000-0000-0000-0003-000000000002',
 4, 'Krit is reliable and friendly. Very smooth tour. Will book again.', '2026-04-04 12:00:00'),
('00000000-0000-0000-0022-000000000003', '00000000-0000-0000-0015-000000000045', '00000000-0000-0000-0002-000000000004', '00000000-0000-0000-0003-000000000004',
 5, 'Somchai handled the Golden Triangle route perfectly. Excellent knowledge.', '2026-04-05 12:00:00'),
('00000000-0000-0000-0022-000000000004', '00000000-0000-0000-0015-000000000046', '00000000-0000-0000-0002-000000000005', '00000000-0000-0000-0003-000000000006',
 5, 'Thanat made the Ayutthaya trip smooth. Guests were very happy.', '2026-04-17 12:00:00');

INSERT INTO em_reviews (em_review_id, job_id, fl_id, em_id, rating, comment, reviewed_at) VALUES
('00000000-0000-0000-0023-000000000001', '00000000-0000-0000-0015-000000000043', '00000000-0000-0000-0003-000000000001', '00000000-0000-0000-0002-000000000001',
 5, 'Travel Everywhere provides clear job details and always pays on time. Great employer.', '2026-04-03 14:00:00'),
('00000000-0000-0000-0023-000000000002', '00000000-0000-0000-0015-000000000044', '00000000-0000-0000-0003-000000000002', '00000000-0000-0000-0002-000000000003',
 4, 'Phuket VIP Tours is professional and well-organized. Easy to work with.', '2026-04-04 14:00:00'),
('00000000-0000-0000-0023-000000000003', '00000000-0000-0000-0015-000000000045', '00000000-0000-0000-0003-000000000004', '00000000-0000-0000-0002-000000000004',
 5, 'Chiang Rai Discovery Tours always sends detailed customer info in advance.', '2026-04-05 14:00:00'),
('00000000-0000-0000-0023-000000000004', '00000000-0000-0000-0015-000000000047', '00000000-0000-0000-0003-000000000007', '00000000-0000-0000-0002-000000000002',
 4, 'Chiang Mai Explorer Tours gives good briefings. Prompt payment.', '2026-04-22 14:00:00');
